package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system time.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with New; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	capacity  float64   // max tokens
	tokens    float64   // current tokens
	rate      float64   // tokens per second
	last      time.Time // last refill time
	clock     Clock
	maxBurstN int // cap on n in AllowN to prevent overflow abuse
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate,
// or a non-positive max burst.
var ErrInvalidConfig = errors.New("ratelimit: capacity, rate, and maxBurst must be > 0")

// New creates a Limiter with the given burst capacity (tokens), refill
// rate (tokens per second), and maximum allowed n per AllowN call.
// If clock is nil, the real clock is used.
func New(capacity, rate float64, maxBurstN int, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 || maxBurstN <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		capacity:  capacity,
		tokens:    capacity,
		rate:      rate,
		last:      clock.Now(),
		clock:     clock,
		maxBurstN: maxBurstN,
	}, nil
}

// AllowN reports whether n tokens are available at time now, consuming
// them if so. Tokens refill continuously at the configured rate, capped
// at capacity.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 || n > l.maxBurstN {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since last update.
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
